contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}
    function run(uint val) public {
        uint before = c.MinSum(); if (__ESBMC_reverted()) return;
        c.SetMinSum(val); if (__ESBMC_reverted()) return;
        uint afterv = c.MinSum(); if (__ESBMC_reverted()) return;
        assert(afterv == val && (before != afterv || before == val));
    }
}

